// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }

    function testFuzz_property(address receiver, uint256 amount) public {
        vm.assume(receiver != address(0));
        amount = bound(amount, 1, type(uint128).max);
        vm.deal(address(c), type(uint128).max);

        vm.prank(address(this)); // deployer is owner
        try c.sendTo(receiver, amount) {
            assertTrue(address(c).balance == type(uint128).max - amount);
        } catch {
            assertTrue(address(c).balance == type(uint128).max);
        }
    }
}
